package com.acme.library.graphql;

import com.acme.library.domain.Book;
import com.acme.library.graphql.generated.DgsConstants;
import com.acme.library.graphql.generated.DgsConstants.BOOK;
import com.acme.library.graphql.generated.DgsConstants.MUTATION;
import com.acme.library.service.BookService;
import com.netflix.graphql.dgs.DgsComponent;
import com.netflix.graphql.dgs.DgsData;
import com.netflix.graphql.dgs.DgsMutation;
import com.netflix.graphql.dgs.DgsQuery;
import com.netflix.graphql.dgs.InputArgument;
import org.springframework.security.access.prepost.PreAuthorize;

/** Netflix DGS resolvers; DgsConstants is generated by the DGS codegen (not in the repository). */
@DgsComponent
public class BookDatafetcher {

    private final BookService bookService;

    public BookDatafetcher(BookService bookService) {
        this.bookService = bookService;
    }

    @DgsData(parentType = DgsConstants.QUERY_TYPE, field = DgsConstants.QUERY.Book)
    public Book book(@InputArgument("id") String id) {
        return bookService.find(id);
    }

    @DgsMutation(field = MUTATION.AddBook)
    @PreAuthorize("hasRole('LIBRARIAN')")
    public Book addBook(@InputArgument("title") String title, @InputArgument("authorId") String authorId) {
        return bookService.add(title, authorId);
    }

    @DgsData(parentType = BOOK.TYPE_NAME, field = BOOK.Author)
    public String author(Book book) {
        return book.authorId();
    }
}
